* Whatever 'size' is, it should be a multiple of 3, or the output* buffer may be overruntrue2high	STARTnumbytes	equ	1	sub	(4:inptr,4:size,4:outptr),space	ldy	#0bankloop	anop	ldy	#65535	lda	size+2	bne	*+5	ldy	size	sta	numbytesloop	anop	lda	[inptr],y               and	#$FF	asl	a	tax	lda	|r_table,x	sta   tmp0	iny	lda	[inptr],y               and	#$FF	asl	a	tax	lda	|g_table,x	ora	tmp0	sta	tmp0	iny	lda	[inptr],y               and	#$FF	asl	a	tax	lda	|b_table,x	ora	tmp0               iny	sta	[outptr],y	lda	outptr	clc	adc	#2	sta	outptr	bcc	*+4	inc	outptr+2               cpy   <numbytes               bne   loop	lda	inptr	clc	adc	<numbytes	sta	inptr	bcc	*+4	inc	inptr+2	lda	size	sec	sbc	<numbytes	sta	size	lda	size+2	sbc	#0	sta	size+2               bcc	done               ; if we had to borrow, we've overrun!	ora	size	bne	bankloopdone	anop               retr_table        anop	256i2'0'g_table	anop	256i2'0'b_table	anop	256i2'0'               END